#!/usr/bin/env bash
set -euo pipefail

# Focused regressions for the read-only collaboration dashboard, content-free OTLP
# JSONL export, explicit editor launch adapters, and retired semantic-eval
# migration. Every fixture lives below TMP; no real provider or GUI is called.

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd -P)"
# shellcheck source=tests/lib/smoke-env.sh
. "$ROOT/tests/lib/smoke-env.sh"
# Interactive fixtures allocate and answer their own private PTYs.

fail() {
  echo "FAIL: $*" >&2
  exit 1
}

operator_materialize() {
  cat > "$TMP/operator_tools_shards.py" <<'PY'
"""Deterministic section ownership for the canonical operator suite."""
import ast
from collections import Counter
import os
import json
from pathlib import Path
import re
import runpy
import sys

# Keep each dependent integration chain together. Independent buckets own
# their protocol fixture and never replay assertions to reconstruct state.
SECTIONS = (
    ("core", 0, None),
    ("shared-cache", 1, "operator_tools_shared_cache.py"),
    ("native-pty", 1, "operator_tools_native_pty.py"),
    ("dispatch-exit", 2, "operator_tools_dispatch_exit.py"),
    ("worker-leases", 3, "operator_tools_worker_leases.py"),
    ("dispatch-results", 1, "operator_tools_dispatch_results.py"),
    ("salvage", 1, "operator_tools_salvage.py"),
    ("scratch-state", 2, "operator_tools_scratch_state.py"),
    ("auto-review", 1, "operator_tools_auto_review.py"),
    ("room-rollover", 2, "operator_tools_room_rollover.py"),
)
# These bodies leave core before execution; no assertions replay to rebuild their fixtures.
INLINE_SECTIONS = {"salvage", "scratch-state", "auto-review", "room-rollover", "dispatch-results"}
LIB = Path(__file__).resolve().parent
SOURCE = Path(sys.argv[1]) if __name__ == "__main__" and len(sys.argv) > 1 else None


def shard(spec):
    if not re.fullmatch(r"[1-9][0-9]*/[1-9][0-9]*", spec):
        raise ValueError("shard must be I/N with positive decimal integers")
    index, total = map(int, spec.split("/"))
    if not 1 <= index <= total <= 4:
        raise ValueError("shard index must be in 1..N and N in 1..4")
    return index, total


def selected(name, spec):
    index, total = shard(spec)
    bucket = next(bucket for section, bucket, _ in SECTIONS if section == name)
    return bucket % total == index - 1


def self_check(total):
    names = [name for name, _, _ in SECTIONS]
    if len(set(names)) != len(names):
        raise ValueError("duplicate operator section")
    files = [filename for _, _, filename in SECTIONS if filename]
    source = SOURCE.read_text(encoding="utf-8")
    markers = re.findall(r'^# OPERATOR_SECTION_BEGIN ([a-z_-]+)$', source, re.M)
    ends = re.findall(r'^# OPERATOR_SECTION_END ([a-z_-]+)$', source, re.M)
    if Counter(markers) != Counter(ends) or any(count != 1 for count in Counter(markers).values()):
        raise ValueError("unassigned or duplicated operator section marker")
    discovered = {"operator_tools_" + name + ".py" for name in markers}
    if len(set(files)) != len(files) or set(files) != discovered:
        raise ValueError("unassigned or duplicated operator section file")
    source = SOURCE.read_text(encoding="utf-8")
    calls = re.findall(r'^_operator_run\("([a-z-]+)"\)$', source, re.M)
    expected = [name for name in names if name not in {"core", "shared-cache", "native-pty"}]
    if Counter(calls) != Counter(expected):
        raise ValueError("unassigned or duplicated operator section call")
    if len(re.findall(r'^if \[ "\$OPERATOR_CORE" = 1 \]; then$', source, re.M)) != 2:
        raise ValueError("core fixture and assertion guards are incomplete")
    if len(re.findall(r'^if os.name == "posix" and operator_selected_py\("native-pty"\):$', source, re.M)) != 1:
        raise ValueError("native-pty must have exactly one guard")
    fixtures = re.findall(r'^# OPERATOR_FIXTURE_BEGIN ([a-z_]+)$', source, re.M)
    fixture_ends = re.findall(r'^# OPERATOR_FIXTURE_END ([a-z_]+)$', source, re.M)
    if Counter(fixtures) != Counter({"provider": 1, "pty": 1, "control": 1}) or Counter(fixtures) != Counter(fixture_ends):
        raise ValueError("unassigned or duplicated operator fixture")
    if len(re.findall(r'^PYTHONDONTWRITEBYTECODE=1 python3 - "\$ROOT/scripts/lib" "\$TMP"', source, re.M)) != 1:
        raise ValueError("shared-cache must have exactly one call")
    core = source.split("# OPERATOR_CORE_BEGIN\n", 1)[1].split("# OPERATOR_CORE_END\n", 1)[0]
    assertions = lambda body: Counter(ast.dump(node) for node in ast.walk(ast.parse(body)) if isinstance(node, ast.Assert))
    actual = assertions((LIB / "operator_tools_core.py").read_text(encoding="utf-8"))
    for name in INLINE_SECTIONS:
        actual.update(assertions(extract(source, name.replace("-", "_"))))
    if actual != assertions(core):
        raise ValueError("core extraction lost or duplicated assertions")
    for filename in files + ["operator_tools_fixture.py", "operator_tools_core.py"]:
        if filename == "operator_tools_shared_cache.py":
            body = extract(source, "shared_cache")
            body = body.split("\n", 1)[1].rsplit("\nPY\n", 1)[0]
        else:
            body = (LIB / filename).read_text(encoding="utf-8")
        ast.parse(body, filename)
    assignments = [name for index in range(1, total + 1)
                   for name in names if selected(name, f"{index}/{total}")]
    if Counter(assignments) != Counter(names):
        raise ValueError("operator sections are unassigned or duplicated")
    return [(name, bucket % total + 1) for name, bucket, _ in SECTIONS]


def extract(source, name, fixture=False):
    prefix = "OPERATOR_FIXTURE" if fixture else "OPERATOR_SECTION"
    return source.split("# " + prefix + "_BEGIN " + name + "\n", 1)[1].split(
        "# " + prefix + "_END " + name + "\n", 1)[0]


def materialize(source_path):
    source = source_path.read_text(encoding="utf-8")
    imports = """import hashlib, importlib.util, io, json, os, re, shlex, shutil, subprocess, sys, time, uuid, threading
from pathlib import Path
from copy import deepcopy
from unittest.mock import Mock, patch
sys.path.insert(0, str(root / 'scripts/lib'))
import terminal_panel as panel, room
import codex_app_notify, panel_results, panel_debate
import panel_results as panel_result_store
import panel_view as question_view
from contextlib import redirect_stderr
from dashboard_projection import display_width
from panel_view import render, inbox_items, needs_strip, attention_items, wrapped, use_unicode
from panel_input import passive_click
from room_view import render_graph, plan_rows as render_plan_rows
from panel_routing import allocate
def fixture_provider_catalog(providers=None):
    rows = [{"provider": name, "binary": name, "installed": True, "models": []}
            for name in ("claude", "codex", "pi")]
    if providers:
        requested = set(providers.split(",")) if isinstance(providers, str) else set(providers)
        rows = [row for row in rows if row["provider"] in requested]
    return rows
"""
    core = source.split("# OPERATOR_CORE_BEGIN\n", 1)[1].split("# OPERATOR_CORE_END\n", 1)[0]
    for name in INLINE_SECTIONS:
        core = core.replace(extract(source, name.replace("-", "_")), "")
    (LIB / "operator_tools_core.py").write_text(core, encoding="utf-8")
    pty = extract(source, "pty", fixture=True).replace(' and operator_selected_py("native-pty")', '')
    (LIB / "operator_pty_helper.py").write_text(pty, encoding="utf-8")
    fixture = imports + extract(source, "provider", fixture=True) + pty + extract(source, "control", fixture=True)
    (LIB / "operator_tools_fixture.py").write_text(fixture, encoding="utf-8")
    for name, _, filename in SECTIONS:
        if name in {"core", "shared-cache"}:
            continue
        body = extract(source, name.replace('-', '_'))
        if name == "native-pty":
            body = body.replace(' and operator_selected_py("native-pty")', '')
        elif name == "dispatch-exit":
            body += "\nexercise_dispatch_exit_evidence(root, temporary, project, shared, room_owner, room_env)\n"
        elif name == "worker-leases":
            body += "\nwith patch.object(panel, \"provider_catalog\", side_effect=fixture_provider_catalog):\n    exercise_observed_worker_leases()\n"
        (LIB / filename).write_text(body, encoding="utf-8")


def _standalone(name, root, temporary):
    temporary = temporary / name
    temporary.mkdir()
    import os
    os.chdir(temporary)
    namespace = runpy.run_path(str(LIB / "operator_tools_fixture.py"),
                              init_globals={"root": root, "temporary": temporary})
    if name == "dispatch-results":
        panel, call, project = (namespace[k] for k in ("panel", "call", "project"))
        inventory = json.loads(call(["bash", str(panel.ENTRY), "panel", "--repo", str(project),
                                     "--providers", "--json"]))
        namespace["registered"] = {row["provider"]: row for row in inventory["providers"]}
    if name in {"native-pty", "dispatch-exit", "auto-review"}:
        panel, room, call, legacy_main_join = (namespace[k] for k in ("panel", "room", "call", "legacy_main_join"))
        project, environment = namespace["project"], namespace["environment"]
        mains = {}
        for owner in panel.PROVIDERS:
            mains[owner] = call(["bash", str(panel.ENTRY), "agent-events", "--repo", str(project),
                                "start", "--provider", owner, "--tool", "panel-main", "--ref", "panel_role=main",
                                "--then", "starting", "--then", "working"]).strip()
            if name == "native-pty":
                # The preceding core phase closes these simulated owners
                # before native-start assertions. Reproduce only that state.
                call(["bash", str(panel.ENTRY), "agent-events", "--repo", str(project), "transition",
                      "--attempt", mains[owner], "--state", "cancelled"])
        namespace["main_attempts"] = mains
        if name in {"dispatch-exit", "auto-review"}:
            shared = room.create(project, "operator-room", "Shared parser task")
            for owner in panel.PROVIDERS:
                legacy_main_join(project, shared, mains[owner], owner)
                call(["bash", str(panel.ENTRY), "agent-events", "--repo", str(project), "transition",
                      "--attempt", mains[owner], "--state", "cancelled"])
                room.append(project, shared, {"kind": "leave", "participant": mains[owner]}, "Fixture main stopped")
            room_owner = call(["bash", str(panel.ENTRY), "agent-events", "--repo", str(project),
                               "start", "--provider", "claude", "--tool", "panel-main", "--ref", "panel_role=main",
                               "--ref", "panel_model=claude-opus-5-5", "--then", "starting", "--then", "working"]).strip()
            legacy_main_join(project, shared, room_owner, "claude", model="claude-opus-5-5", label="Active Opus")
            namespace.update(shared=shared, room_owner=room_owner,
                             room_env=dict(environment, OMS_ROOM_ID=shared, OMS_ROOM_REPO=str(project),
                                           OMS_ROOM_PARTICIPANT=room_owner, OMS_PANEL_MAIN_ATTEMPT=room_owner))
    filename = next(filename for section, _, filename in SECTIONS if section == name)
    code = compile((LIB / filename).read_text(encoding="utf-8"), str(LIB / filename), "exec")
    if name == "auto-review":
        (namespace["project"] / ".oms/plan").mkdir(parents=True, exist_ok=True)
        # Match the core fixture: these result rows have no supervised child.
        from unittest.mock import patch
        with patch.object(namespace["panel"], "_settle_dispatch", return_value=None):
            exec(code, namespace)
    else:
        exec(code, namespace)
def record_timing(name, started):
    import os
    timing_file = os.environ.get("OMS_OPERATOR_TIMINGS")
    if timing_file:
        elapsed = int(__import__("time").monotonic() - started)
        with open(timing_file, "a", encoding="utf-8") as output:
            output.write("%s\t%s\n" % (elapsed, name))


def standalone(name, root, temporary):
    started = __import__("time").monotonic()
    try:
        return _standalone(name, root, temporary)
    finally:
        record_timing(name, started)


def run_section(name, spec, namespace):
    if not selected(name, spec):
        return
    if os.environ.get("OMS_OPERATOR_SOCKET_DENIED") == "1" and name == "native-pty":
        print("operator-native-pty: skipped (sandbox denies unix sockets)", flush=True)
        return
    if spec != "1/1":
        # Fresh state for independent sections, including when N folds a
        # bucket into the core shard. Restore cwd before continuing core.
        import os
        from unittest.mock import patch
        before = Path.cwd()
        try:
            with patch.dict(os.environ):
                standalone(name, namespace["root"], namespace["temporary"])
        finally:
            os.chdir(before)
    else:
        started = __import__("time").monotonic()
        filename = next(filename for section, _, filename in SECTIONS if section == name)
        exec(compile((LIB / filename).read_text(encoding="utf-8"), str(LIB / filename), "exec"), namespace)
        record_timing(name, started)


def main(args):
    if len(args) == 2 and args[0] == "--progress":
        import time
        current, started, reported = "", time.monotonic(), time.monotonic()
        while True:
            label = Path(args[1]).read_text(encoding="utf-8").strip()
            now = time.monotonic()
            if label and label != current:
                if current:
                    print("operator-core: %s ok (%ds)" % (current, now - started), flush=True)
                    record_timing("core/" + current, started)
                if label == "done":
                    return
                current, started, reported = label, now, now
                print("operator-core: %s started" % current, flush=True)
            elif now - reported >= 45:
                print("operator-core: %s running (%ds)" % (current, now - started), flush=True)
                reported = now
            time.sleep(1)
    materialize(SOURCE)
    mode = args[0] if args else "--self-check"
    if mode == "--selection" and len(args) == 2:
        index, total = shard(args[1])
        self_check(total)
        print(int(selected("core", args[1])), int(selected("shared-cache", args[1])), f"{index}/{total}")
    elif mode in {"--list", "--self-check"} and len(args) <= 2:
        total = int(args[1]) if len(args) == 2 else 4
        shard(f"1/{total}")
        for name, index in self_check(total):
            print(f"{index}/{total}\t{name}")
    elif mode == "--standalone" and len(args) == 4:
        root, temporary, spec = Path(args[1]), Path(args[2]), args[3]
        self_check(shard(spec)[1])
        for name, _, _ in SECTIONS:
            if name not in {"core", "shared-cache"} and selected(name, spec):
                if os.environ.get("OMS_OPERATOR_SOCKET_DENIED") == "1" and name == "native-pty":
                    print("operator-native-pty: skipped (sandbox denies unix sockets)", flush=True)
                    continue
                standalone(name, root, temporary)
    else:
        raise ValueError("invalid operator shard runner arguments")


if __name__ == "__main__":
    try:
        main(sys.argv[2:])
    except (ValueError, StopIteration) as error:
        print("error: " + str(error), file=sys.stderr)
        sys.exit(2)
PY
}

# A sandbox may deny AF_UNIX even when tmux and PTY support are installed.
# Probe the exact capability in TMP so workers can report partial coverage.
OPERATOR_SOCKET_DENIED=0
if python3 - "${TMPDIR:-/tmp}" <<'PY'
import os
import socket
import sys
path = os.path.join(sys.argv[1], "socket-probe")
probe = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
try:
    probe.bind(path)
except (OSError, AttributeError):
    sys.exit(1)
finally:
    probe.close()
try:
    os.unlink(path)
except OSError:
    pass
PY
then
  :
else
  OPERATOR_SOCKET_DENIED=1
fi
OPERATOR_SOCKET_SKIPS=0
export OMS_OPERATOR_SOCKET_DENIED="$OPERATOR_SOCKET_DENIED"
operator_skip_socket_section() {
  if [ "$OPERATOR_SOCKET_DENIED" = 1 ]; then
    echo "operator-$1: skipped (sandbox denies unix sockets)"
    OPERATOR_SOCKET_SKIPS=$((OPERATOR_SOCKET_SKIPS + 1))
    return 0
  fi
  return 1
}

# Interactive fixtures allocate and answer their own private PTYs.
exec < /dev/null
TMP="$(mktemp -d "${TMPDIR:-/tmp}/oms-operator-tools.XXXXXX")"
operator_cleanup() {
  if [ -n "${OPERATOR_PROGRESS_PID:-}" ]; then
    kill "$OPERATOR_PROGRESS_PID" 2>/dev/null || true
    wait "$OPERATOR_PROGRESS_PID" 2>/dev/null || true
  fi
  if [ -n "${OPERATOR_CORE_STARTED:-}" ] && [ -n "${OMS_OPERATOR_TIMINGS:-}" ]; then
    printf '%s\tcore\n' "$((SECONDS - OPERATOR_CORE_STARTED))" >> "$OMS_OPERATOR_TIMINGS"
  fi
  if [ -n "${OMS_OPERATOR_TIMINGS:-}" ] && [ -z "${OMS_OPERATOR_TIMINGS_DIR:-}" ] && [ -f "$OMS_OPERATOR_TIMINGS" ]; then
    while IFS="$(printf '\t')" read -r duration section; do
      [ -n "$section" ] && echo "operator-section: ${duration}s $section"
    done < <(sort -nr -k1,1 "$OMS_OPERATOR_TIMINGS")
  fi
  if [ "${OPERATOR_SPEC:-1/1}" != 1/1 ] && [ -n "${OMS_OPERATOR_TIMINGS_DIR:-}" ]; then
    printf '%s %s\n' "$OPERATOR_SPEC" "$((SECONDS - OPERATOR_SHARD_STARTED))" > "$OMS_OPERATOR_TIMINGS_DIR/operator-shard.${OPERATOR_SPEC%/*}"
  fi
  rm -rf "$TMP"
}
trap operator_cleanup EXIT
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM
# Tier routing only routes to providers on PATH. CI hosts have no provider CLIs, so inert
# stand-ins sit last on PATH; a developer's real CLIs still win and no fixture executes them.
mkdir -p "$TMP/provider-standins"
for provider in claude codex; do
  printf '#!/bin/sh\necho "%s stand-in: not a real CLI" >&2\nexit 1\n' "$provider" > "$TMP/provider-standins/$provider"
  chmod +x "$TMP/provider-standins/$provider"
done
PATH="$PATH:$TMP/provider-standins"
oms_smoke_use_fixture_root
export OMS_LOCK_DIR="$TMP/locks"
mkdir -p "$OMS_LOCK_DIR"
OPERATOR_STARTED=$SECONDS
OPERATOR_SHARD_STARTED=$SECONDS
operator_materialize
OPERATOR_SPEC="${OMS_OPERATOR_SHARD:-1/1}"
OPERATOR_MODE=run
case "${1:-}" in
  --jobs)
    [ "$#" = 2 ] || fail '--jobs requires N'
    # shellcheck source=scripts/lib/check-parallel.sh
    . "$ROOT/scripts/lib/check-parallel.sh"
    python3 "$TMP/operator_tools_shards.py" "${BASH_SOURCE[0]}" --self-check "$2"
    OMS_OPERATOR_TIMINGS_DIR="$TMP"
    export OMS_OPERATOR_TIMINGS_DIR
    # The jobs summary replaces the ordinary cleanup trap in the parent.
    operator_timing_summary() {
      if [ -d "$OMS_OPERATOR_TIMINGS_DIR" ]; then
        while IFS="$(printf '\t')" read -r duration section; do
          [ -n "$section" ] && echo "operator-section: ${duration}s $section"
        done < <(cat "$OMS_OPERATOR_TIMINGS_DIR"/operator-timings.* 2>/dev/null | sort -nr -k1,1)
        for timing in "$OMS_OPERATOR_TIMINGS_DIR"/operator-shard.*; do
          [ -f "$timing" ] || continue
          read -r shard duration < "$timing"
          echo "operator-shard: $shard ${duration}s"
        done
      fi
      rm -rf "$TMP"
    }
    trap operator_timing_summary EXIT
    if [ "$OPERATOR_SOCKET_DENIED" = 1 ]; then
      OMS_OPERATOR_PARTIAL_MARKER_DIR="$TMP"
      export OMS_OPERATOR_PARTIAL_MARKER_DIR
      if OMS_OPERATOR_PROGRESS=1 oms_operator_parallel "${BASH_SOURCE[0]}" "$2" 3>&1; then
        parallel_status=0
      else
        parallel_status=$?
      fi
      partial_count=0
      for marker in "$TMP"/operator-partial.*; do
        [ -f "$marker" ] && partial_count=$((partial_count + 1))
      done
      if [ "$parallel_status" -ne 0 ] && [ "$partial_count" -eq "$2" ]; then
        exit 77
      fi
      exit "$parallel_status"
    fi
    # Shard logs are buffered by the shared runner; progress keeps its own stream.
    OMS_OPERATOR_PROGRESS=1 oms_operator_parallel "${BASH_SOURCE[0]}" "$2" 3>&1
    exit $? ;;
  --list|--self-check)
    [ "$#" -le 2 ] || fail 'expected --list [N] or --self-check [N]'
    exec_args=("$1" "${2:-4}")
    OPERATOR_MODE=list ;;
  --shard)
    [ "$#" = 2 ] || fail '--shard requires I/N'
    OPERATOR_SPEC="$2" ;;
  -h|--help)
    echo 'usage: operator-tools-smoke.sh [--shard I/N | --jobs N | --list [N] | --self-check [N]] (N=1..4)'
    echo 'OMS_OPERATOR_SHARD=I/N also selects a shard; no selector runs every section.'
    exit 0 ;;
  '') ;;
  *) fail "unknown argument: $1" ;;
esac
unset OMS_OPERATOR_SHARD
if [ "$OPERATOR_MODE" = list ]; then
  python3 "$TMP/operator_tools_shards.py" "${BASH_SOURCE[0]}" "${exec_args[@]}"
  exit $?
fi
OPERATOR_SELECTION="$(python3 "$TMP/operator_tools_shards.py" "${BASH_SOURCE[0]}" --selection "$OPERATOR_SPEC" | tr -d '\r')"
read -r OPERATOR_CORE OPERATOR_CACHE OPERATOR_SPEC <<< "$OPERATOR_SELECTION"
if [ "$OPERATOR_SOCKET_DENIED" = 1 ]; then
  [ "$OPERATOR_CORE" = 1 ] && operator_skip_socket_section core || true
  if [ "$((2 % ${OPERATOR_SPEC#*/} + 1))" = "${OPERATOR_SPEC%/*}" ]; then
    operator_skip_socket_section room-rollover || true
  fi
fi
if [ -n "${OMS_OPERATOR_TIMINGS_DIR:-}" ] && [ "$OPERATOR_SPEC" != 1/1 ]; then
  OMS_OPERATOR_TIMINGS="$OMS_OPERATOR_TIMINGS_DIR/operator-timings.${OPERATOR_SPEC%/*}"
  export OMS_OPERATOR_TIMINGS
fi
if [ -z "${OMS_OPERATOR_TIMINGS:-}" ]; then
  OMS_OPERATOR_TIMINGS="$TMP/operator-timings.single"
  export OMS_OPERATOR_TIMINGS
fi

if [ "$OPERATOR_CORE" = 1 ]; then
OPERATOR_CORE_STARTED=$SECONDS
operator_core_block() {
  printf '%s\n' "$1" > "$TMP/operator-core-progress"
}
operator_core_block dashboard-fixtures
if [ "${OMS_OPERATOR_PROGRESS:-0}" = 1 ]; then
  python3 "$TMP/operator_tools_shards.py" "${BASH_SOURCE[0]}" --progress "$TMP/operator-core-progress" >&3 &
else
  python3 "$TMP/operator_tools_shards.py" "${BASH_SOURCE[0]}" --progress "$TMP/operator-core-progress" &
fi
OPERATOR_PROGRESS_PID=$!
repo="$TMP/repo with space"
mkdir -p "$repo/.oms/artifacts" "$repo/.oms/hooks" "$repo/.oms/plan" \
  "$repo/.oms/delegations" "$repo/.oms/lifecycle" \
  "$TMP/state/oh-my-setting/approvals"
git -C "$repo" init -q
git -C "$repo" config user.email test@example.com
git -C "$repo" config user.name test
printf 'old\n' > "$repo/value.txt"
printf '*\n' > "$repo/.oms/.gitignore"
git -C "$repo" add value.txt
git -C "$repo" commit -qm init
base_sha="$(git -C "$repo" rev-parse HEAD)"

# One real patch subject for the artifact readers. Restore the fixture
# immediately so read-only tools must leave the primary checkout unchanged.
printf 'new\n' > "$repo/value.txt"
git -C "$repo" diff --binary -- value.txt > "$repo/.oms/artifacts/change.patch"
git -C "$repo" checkout -- value.txt

OMS_FIXTURE_REPO="$repo" OMS_FIXTURE_BASE="$base_sha" OMS_FIXTURE_PID="$$" \
  OMS_FIXTURE_STATE="$TMP/state" \
python3 - <<'PY'
import hashlib
import json
import io
import inspect
import os
from pathlib import Path

repo = Path(os.environ["OMS_FIXTURE_REPO"])
state_home = Path(os.environ["OMS_FIXTURE_STATE"])
base = os.environ["OMS_FIXTURE_BASE"]
patch = repo / ".oms" / "artifacts" / "change.patch"
patch_hash = hashlib.sha256(patch.read_bytes()).hexdigest()
rows = [
    {
        "schema": 1,
        "event_id": "evt_call",
        "operation_id": "op_one",
        "artifact_id": "sha256:" + "1" * 64,
        "ts": "2026-08-01T00:00:05Z",
        "kind": "call",
        "provider": "codex",
        "exit": 0,
        "verify_exit": "PRIVATE-VERIFY-EXIT",
        "run_id": "run_one",
        "selected_model": "gpt-test",
        "served_model": "gpt-served",
        "model_attribution": "transport",
        "cost_usd": 0.25,
        "model_class": "explicit",
        "reasoning_effort": "medium",
