import threading
parallel_call = "call-f6f6f6f6f6f6f6f6"
parallel_attempt = dict(auto_attempt, attempt_id="attempt-settlement-parallel",
    refs=dict(auto_attempt["refs"], panel_room_participant=parallel_call))
