def observe_control_launch(argv, *args, **kwargs):
    if (argv[:3] == [sys.executable, "-c", "pass"]
            or argv[5:8] == [sys.executable, "-c", "pass"]):
        control_launch.update(env=kwargs["env"])
    return real_popen(argv, *args, **kwargs)
