                          ("researcher", "worker", "gpt-6-luna"), ("explorer", "worker", "gpt-6-luna"),
                          ("builder", "worker", "claude-sonnet-5-5")):
    flow_members.append({"participant": ident, "role": role, "model": model, "joined": True,
