assert opened == "%9" and calls[-2:] == [
    ["split-window", "-d", "-v", "-b", "-l", "24", "-t", "%2", "-c", "/repo", "-P", "-F", "#{pane_id}", "CMD"],
    ["set-option", "-p", "-t", "%9", "@oms_panel_reader", "%1"]], calls
