                        expected = {"plan": "wheel Scroll", "messages": "↑↓ Message" if nav.get("message_ids") else "←→ Filter"}.get(initial_tab)
                        assert not expected or not nav.get("tab_body_visible") or expected in full.splitlines()[-1], full
                nav["tab"] = initial_tab
