renames = []
class TmuxStub:
    def __init__(self, name):
        self.name = name
    def __call__(self, command, **kwargs):
        if "rename-window" in command:
            renames.append(command[-1])
            self.name = command[-1]
        return subprocess.CompletedProcess(command, 0, self.name + "\n" if "display-message" in command else "")
