    with patch.object(panel_results, "_records", return_value=([], admission_records + [{}] * (1000 - len(admission_records)))):
        assert panel_results.pending_admissions(Path("."), {"pending", "missing", "admitted", "landed", "no-patch"}) == {"pending", "missing"}
