                  "reviewer": ("done", 30), "researcher": ("done", 40)}.get(attempt["attempt_id"], (attempt["state"], 0))
    attempt.update(state=state, updated_at=minutes_ago(age))
queue["awaiting_admission"] = ["reviewer"]
