            while len(restored) < len(safe):
                assert body[cursor].startswith(marker), (width, original, body[cursor])
                restored += body[cursor][len(marker):]
                cursor += 1
            assert restored == safe, (width, restored, safe)
        assert cursor == len(body), body[cursor:]
